CREATE TABLE IF NOT EXISTS public.user_roles (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'buyer'); GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read own marketplace role" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid()); INSERT INTO public.user_roles(user_id,role) SELECT id,role FROM public.profiles ON CONFLICT DO NOTHING;
ALTER TABLE public.wave_orders ADD COLUMN IF NOT EXISTS payment_method text NOT NULL DEFAULT 'mtn-momo' CHECK (payment_method IN ('mtn-momo','cash')); ALTER TABLE public.wave_orders ADD COLUMN IF NOT EXISTS cancelled_at timestamptz;
CREATE OR REPLACE FUNCTION public.setup_marketplace_profile(_name text, _role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'sign-in-required'; END IF; IF length(trim(_name))<1 OR length(_name)>100 THEN RAISE EXCEPTION 'name-required'; END IF; INSERT INTO profiles(id,name,role) VALUES(auth.uid(),trim(_name),_role) ON CONFLICT(id) DO UPDATE SET name=excluded.name,role=excluded.role; INSERT INTO user_roles(user_id,role) VALUES(auth.uid(),_role) ON CONFLICT(user_id) DO UPDATE SET role=excluded.role; END $$; REVOKE ALL ON FUNCTION public.setup_marketplace_profile(text,public.app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.setup_marketplace_profile(text,public.app_role) TO authenticated;
CREATE OR REPLACE FUNCTION public.choose_cash(_order_id uuid,_buyer uuid) RETURNS public.wave_orders LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o wave_orders; BEGIN SELECT * INTO o FROM wave_orders WHERE id=_order_id FOR UPDATE; IF o.id IS NULL OR o.buyer_id<>_buyer OR o.cancelled_at IS NOT NULL THEN RAISE EXCEPTION 'not-your-order'; END IF; IF EXISTS(SELECT 1 FROM payments WHERE order_id=o.id AND status IN ('pending','successful')) THEN RAISE EXCEPTION 'momo-payment-in-progress'; END IF; UPDATE wave_orders SET payment_method='cash' WHERE id=o.id RETURNING * INTO o; RETURN o; END $$;
CREATE OR REPLACE FUNCTION public.confirm_cash(_order_id uuid,_buyer uuid) RETURNS public.wave_orders LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o wave_orders; BEGIN SELECT * INTO o FROM wave_orders WHERE id=_order_id FOR UPDATE; IF o.id IS NULL OR o.buyer_id<>_buyer OR o.cancelled_at IS NOT NULL THEN RAISE EXCEPTION 'not-your-order'; END IF; IF o.payment_method<>'cash' OR o.status NOT IN ('delivered','completed') THEN RAISE EXCEPTION 'cash-requires-delivery'; END IF; UPDATE wave_orders SET status='completed',completed_at=coalesce(completed_at,now()) WHERE id=o.id RETURNING * INTO o; RETURN o; END $$;
CREATE OR REPLACE FUNCTION public.cancel_marketplace_wave(_wave_id uuid,_actor uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w waves; o wave_orders; BEGIN SELECT * INTO w FROM waves WHERE id=_wave_id FOR UPDATE; IF w.id IS NULL THEN RAISE EXCEPTION 'wave-not-found'; END IF; SELECT * INTO o FROM wave_orders WHERE wave_id=w.id FOR UPDATE; IF _actor<>w.buyer_id AND (_actor IS DISTINCT FROM w.trader_id) THEN RAISE EXCEPTION 'not-your-wave'; END IF; IF o.id IS NOT NULL THEN IF o.status IN ('delivering','delivered','completed') OR EXISTS(SELECT 1 FROM payments WHERE order_id=o.id AND status IN ('pending','successful')) THEN RAISE EXCEPTION 'cannot-cancel-active-payment-or-delivery'; END IF; UPDATE wave_orders SET cancelled_at=now() WHERE id=o.id; END IF; UPDATE waves SET status='expired' WHERE id=w.id; END $$;
CREATE OR REPLACE FUNCTION public.advance_order(_order_id uuid,_actor uuid,_next public.order_status) RETURNS public.wave_orders LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o wave_orders; paid boolean; BEGIN SELECT * INTO o FROM wave_orders WHERE id=_order_id FOR UPDATE; IF o.id IS NULL OR o.cancelled_at IS NOT NULL THEN RAISE EXCEPTION 'order-not-found'; END IF; IF _next='completed' THEN IF _actor<>o.buyer_id THEN RAISE EXCEPTION 'only-buyer-completes'; END IF; ELSE IF _actor<>o.trader_id THEN RAISE EXCEPTION 'not-your-order'; END IF; END IF; IF o.status=_next THEN RETURN o; END IF; IF NOT ((o.status='accepted' AND _next IN ('preparing','delivering')) OR (o.status='preparing' AND _next IN ('ready','delivering')) OR (o.status='ready' AND _next='delivering') OR (o.status='delivering' AND _next='delivered') OR (o.status='delivered' AND _next='completed')) THEN RAISE EXCEPTION 'bad-transition'; END IF; SELECT EXISTS(SELECT 1 FROM payments WHERE order_id=o.id AND status='successful') INTO paid; IF o.payment_method<>'cash' AND NOT paid THEN RAISE EXCEPTION 'payment-required'; END IF; IF _next='completed' AND NOT paid THEN RAISE EXCEPTION 'use-cash-confirmation'; END IF; UPDATE wave_orders SET status=_next,delivered_at=CASE WHEN _next='delivered' THEN now() ELSE delivered_at END,completed_at=CASE WHEN _next='completed' THEN now() ELSE completed_at END WHERE id=o.id RETURNING * INTO o; RETURN o; END $$;
REVOKE ALL ON FUNCTION public.choose_cash(uuid,uuid),public.confirm_cash(uuid,uuid),public.cancel_marketplace_wave(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.choose_cash(uuid,uuid),public.confirm_cash(uuid,uuid),public.cancel_marketplace_wave(uuid,uuid) TO service_role;
CREATE POLICY "Wave counterparties read profiles" ON public.profiles FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM wave_orders o WHERE (o.buyer_id=auth.uid() AND o.trader_id=profiles.id) OR (o.trader_id=auth.uid() AND o.buyer_id=profiles.id)));
